const meta = $('Normalizar entrada').first().json;
const items = $input.all();
let text = '';

if (meta.extension === 'csv') {
  const rows = items.map(i => i.json);
  const headers = Object.keys(rows[0] || {});
  text = rows
    .map((r, idx) => `Linha ${idx + 1}: ` + headers.map(h => `${h}: ${r[h]}`).join(' | '))
    .join('\n');
} else {
  text = items.map(i => i.json.text ?? i.json.data ?? '').join('\n');
}

if (!text.trim()) {
  throw new Error(`Documento ${meta.documentId} sem texto extraível`);
}

return [{ json: { ...meta, text } }];

const meta = $('Normalizar entrada').first().json;
const chunks = $('Chunking (ai-service)').first().json.chunks || [];
const embeddings = $input.first().json.embeddings || [];

if (!chunks.length) {
  throw new Error(`Nenhum chunk gerado para o documento ${meta.documentId}`);
}
if (chunks.length !== embeddings.length) {
  throw new Error(`Chunks (${chunks.length}) e embeddings (${embeddings.length}) divergem`);
}
const bad = embeddings.findIndex(v => !Array.isArray(v) || v.length !== 1024);
if (bad !== -1) {
  throw new Error(`Embedding ${bad} não tem 1024 dimensões (esperado para bge-m3)`);
}

const payload = chunks.map((c, i) => ({
  chunk_index: c.index ?? i,
  content: c.content,
  metadata: { ...(c.metadata || {}), filename: meta.filename },
  embedding: embeddings[i],
}));

return [{ json: { ...meta, text: undefined, chunks: payload } }];

const r = $input.first().json;
const sources = r.sources || [];

// Assistência estrita: sem evidência recuperada, não há resposta.
if (!sources.length) {
  return [{ json: { output: 'Não encontrei essa informação na base de conhecimento deste projeto.' } }];
}

const refs = sources
  .map((s, i) => `[${i + 1}] ${s.filename ?? s.document_id ?? 'fonte'}${s.chunk_index != null ? ' (trecho ' + s.chunk_index + ')' : ''}`)
  .join('\n');

return [{ json: { output: `${r.answer}\n\nFontes:\n${refs}` } }];

